INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lion', 'Lion is a life simulator, much like it''s predecessor, Wolf. You take the role of a lion or lioness and live you life on the plains of Africa, performing duties that real life lions share, such as hunting, raising cubs, and defending your territory. There are several maps to choose from, and many environmental and game play settings are customization, in a sandbox-like fashion. There are no ultimate goals, it is open world and you may do as you please.' FROM games WHERE igdb_id = 9565 ON CONFLICT (game_id, language_code) DO NOTHING;
