INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Power Dolls: Detachment of Limited Line Service', 'In the year 2535, planet Omni entered independence war against planet Earth government for land dispute. Facing the overwhelming Earth forces, Omni government converted the pioneering Power Loader (PLD) units into walking combat machines. In 2540, the third team of 177th squadron, an all-female combat group named DoLLS (Detachment of Limited Line Service) has seen deployment.' FROM games WHERE igdb_id = 50326 ON CONFLICT (game_id, language_code) DO NOTHING;
