INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('carrier-aces', 42632, '1995-07-28', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5yt2.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc6dr0.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Carrier Aces', 'Carrier Aces is a 3rd person flight simulator that takes place during World War II. The game is also entirely split screen, with a second player or the computer opponent taking the controls on the second half of the secreen. Players control an aircraft pilot of either the United States or Japanese Empire. Based aboard an aircraft carrier, the player can engage in the following missions: 1vs1 dogfights, strafing runs on enemy ships, dive bombing on enemy ships, torpedo runs on enemy ships and carrier landings. All missions are made up of these elements, however campaign missions also feature the ability to decide which aircraft to bring into battle, each with it''s own statistics, and keep track of progress on an area map. When two forces engage each other on this map, players can choose which plane to bring into battle and it will close in a 1vs1 battle with the enemy. In dogfights, both players control an aircraft whereas during ship combat, one player controls an aircraft and the other will control the ship''s turret gun. Aircraft controls include being able to tilt left and right, climb, dive, increase speed, decrease speed, fire guns, release bombs/torpedoes (if present) and do a 180 degree loop. Turret controls are more limited, only allowing the player to aim left and right, fire the gun and zoom.' FROM games WHERE igdb_id = 42632 ON CONFLICT (game_id, language_code) DO NOTHING;
