INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kamikuishiki-mura Monogatari', 'Kamikuishiki-mura Monogatari is a satirical Japanese doujin resource management strategy game developed by HappySoft and published by Aum Soft. Game satirises the Aum Shinrikyo cult and the 1995 Tokyo subway sarin gas attack orchestrated by the cult. A common misconception is that the game was produced by the cult as propaganda, whereas Kamikuishiki-mura Monogatari actually portrays Aum and the sarin gas attack negatively, mocking its members and showing footage of ''humiliating'' media coverage.' FROM games WHERE igdb_id = 130768 ON CONFLICT (game_id, language_code) DO NOTHING;
