INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Stonekeep', 'Stonekeep is a first-person role-playing game where players explore underground realms to reclaim their immortal soul. Set in sprawling subterranean environments, players navigate through ancient corridors, sewers, and magical realms while battling undead creatures, rescuing allies, and freeing a dragon. The game features both physical and magical combat systems as players uncover a story that develops based on their choices.' FROM games WHERE igdb_id = 253 ON CONFLICT (game_id, language_code) DO NOTHING;
