INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('virtual-chess--1', 351645, '1995-12-06', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coa21x.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scxrp7.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Virtual Chess', 'VirtuaChess is the commercial version of the Écume and Cumulus 2 chess programs (which finished second in the blitz tournament in Munich and which tied 2nd/3rd in the 7th World Championships in Madrid). It runs on a PC with MS-DOS and can use all of the available memory for its hash tables. It has a splendid graphical interface written by the French firm Titus. Most of the chess engine is written in 32 bit assembler, and the program includes dynamic evaluation of king safety and pawn structure. It is based on PVS and uses null-move pruning. The program has perfect knowledge of KPK endgames. The evaluation function attempts to build plans whenever it recognizes important features in a position. VirtuaChess runs at 20,000 nodes per second on a Pentium 90.' FROM games WHERE igdb_id = 351645 ON CONFLICT (game_id, language_code) DO NOTHING;
