INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star Wars: TIE Fighter - Collector''s CD-ROM', 'In 1995, TIE Fighter also received a Collector''s CD-ROM. The CD-ROM version offered optional enhanced SVGA graphics, increasing the game''s resolution from 320x200 to 640x480. The cinematic cutscenes were also enhanced, and the game received numerous voiceovers. The CD-ROM includes the previously released Defender of the Empire expansion and an additional Enemies of the Empire expansion. This CD-ROM also added support for gameplay under Mac OS 8 and Mac OS 9.' FROM games WHERE igdb_id = 22626 ON CONFLICT (game_id, language_code) DO NOTHING;
