INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('anvil-of-dawn', 2427, '1995-12-31', 65, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9d9f.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/p5ampxwuyd81vlf1ig8h.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Anvil of Dawn', 'The world of Tempest is in need of a champion! You have been summoned to embark on a noble journey to save all of humanity from an evil fate. You must keep your wits about you, your sword must stay sharp and ready, and your spells charged as you forge through Tempest''s massive landscape. Descend into the maws of many a dark and dangerous dungeon in search of your quest''s end.
