INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Virtua Fighter Remix', 'Virtua Fighter Remix was an update of the original Virtua Fighter with higher-polygon models, texture mapping, and some gameplay changes. It was given free to all registered Saturn owners in the United States via mail. It also had an arcade release on the ST-V (an arcade platform based on the Sega Saturn) and later ported to Microsoft Windows as Virtua Fighter PC. In Japan, Game Machine listed it on their August 1, 1995 issue as being the twenty-first most-successful arcade game of the year' FROM games WHERE igdb_id = 145524 ON CONFLICT (game_id, language_code) DO NOTHING;
