INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Manx TT Super Bike', 'One of the best games ever on the Saturn. Manx TT Superbikes recreates the top-speed twists and turns of the legendary Isle of Man TT circuits. Throw your high-powered superbike round country lanes and hurtle through villages at hair-raising speeds as one or two riders push their nerves to the absolute limit on the circuit where heroes are made!' FROM games WHERE igdb_id = 36572 ON CONFLICT (game_id, language_code) DO NOTHING;
