INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lemmings 3D', 'Lemmings 3D is a puzzle video game released in 1995, developed by Clockwork Games and published by Psygnosis. The gameplay, like the original Lemmings game, requires the player to lead all the lemmings to their exit by giving them the appropriate "skills". It was the first Lemmings game to be rendered in 3D. It was released for DOS, PlayStation, and Sega Saturn, with all three releases being almost identical minus some performance differences.' FROM games WHERE igdb_id = 13779 ON CONFLICT (game_id, language_code) DO NOTHING;
