INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bakushou!! All Yoshimoto Quiz Ou Ketteisen DX', 'Bakushō!! All Yoshimoto Quiz Ou Ketteisen DX is a quiz game based on the popular TV show Yoshimoto Club. There are two different modes. The first mode has the player going on a fantasy quest to rescue a princess and the player has to answer questions correctly to bypass monsters. The second mode is a classic game show in which the player must answer as many questions correctly as possible to get the highest number of points.' FROM games WHERE igdb_id = 45422 ON CONFLICT (game_id, language_code) DO NOTHING;
