INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Eko Eko Azarak: Wizard of Darkness', 'Eko Eko Azarak: Wizard of Darkness is a sound-novel-style adventure game based on the 1995 horror film of the same title, in turn adapted from the 1975 manga by Shinichi Koga, which tells an original story set in the same universe. High school student and witch Misa Kuroi has been trapped along with 12 other students in her school by a mysterious individual planning to summon the demon Lucifer into the human realm. The game is presented as a sound novel, consisting of long segments of text narration with digitized photo graphics; there are occasional choices for the player to make which can branch the story in various directions.' FROM games WHERE igdb_id = 376543 ON CONFLICT (game_id, language_code) DO NOTHING;
