INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chewy: Escape from F5', 'Chewy: Escape from F5 is an adventure game featuring Chewy, a pink alien protagonist. The plot revolves around Chewy and his partner Clint''s mission to steal the powerful "Red Glum" from the Borkian high security zone F5, aiming to prevent its use by the Borks. After successfully obtaining the Red Glum, Clint''s escape is interrupted when his spaceship is pulled into a wormhole, crash-landing on Earth. The game follows Chewy''s journey as he navigates this unfamiliar planet, facing challenges and puzzles while attempting to reunite with Clint and protect the stolen Red Glum. Combining sci-fi elements, distinctive character design, and planet-based adventure, Chewy: Escape from F5 presents players with an engaging storyline and varied gameplay as they guide the alien through his Earth-bound mission.' FROM games WHERE igdb_id = 47034 ON CONFLICT (game_id, language_code) DO NOTHING;
