INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('kirby-no-omochabako-baseball', 42257, '1995-12-18', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co30de.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8aqu.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kirby no Omochabako: Baseball', 'This is a simple one screened game that featured Kirby being the ball. It plays somewhat like pinball, where the player must hit the ball in one of the scoring slots, or if he fails to make it in any slot, he gets a strike. The goal is to get as many runs as possible, and just aim for a high score. The game technically plays forever or until the player gets 3 outs, but since there is a limited period for broadcasting the Baseball game, it only lasts as long. There is a 2-player mode available.' FROM games WHERE igdb_id = 42257 ON CONFLICT (game_id, language_code) DO NOTHING;
