INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Appare-den: Fukuryuu no Shou', 'Appare-den: Fukuryuu no Shou plays like a traditional top-down Japanese RPG, with world map traveling, random enemies, and turn-based combat. The attacks in combat are animated; after the player has assigned command to all the characters, the animation shows the entire party attack at once. There are also special techniques the heroes can learn and execute in battles.' FROM games WHERE igdb_id = 243782 ON CONFLICT (game_id, language_code) DO NOTHING;
