INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Adventures With Oslo: Tools and Gadgets', 'Five programs in one! An animated storybook about a llama named Dolly who is constantly requiring rescue by Jimmy who turns into the many shapes of simple machines; An adventure game taking you on a search of Tooltown and the Valley of Machines for clues and a surprise ending; A Coloring Gallery featuring musical markers and a tic-tac-toe game; A very colorful Maze Arcade challenging you to navigate five increasingly complex mazes while scoring your performance; And an Interactive Database which uncovers all six classes of simple machines- the inclined plane, screw, pulley, wheel and axle, lever, and wedge.' FROM games WHERE igdb_id = 206095 ON CONFLICT (game_id, language_code) DO NOTHING;
