INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Space Hulk: Vengeance of the Blood Angels', 'Space Hulk: Vengeance of the Blood Angels is a mix of a First-Person-Shooter and a tactical fighting game. It is placed in the Warhammer 40k background of the Games Workshop table top games. It is the successor of the PC game Space Hulk from 1993 and it tells of the fight between the imperial Terminator Chapters and the Tyranid Gene Stealers.
