INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'RPG Tsukuuru 2', 'RPG Tsukuuru 2 is a Satellaview-compatible Slotted Cartridge game belonging to ASCII''s Tsukuuru series. The title of these games are portmanteau-word puns mixing the Japanese word tsukuru, which means "make" or "create", with tsuuru, the Japanese transcription of the English word "tool". As the title suggests, this RPG creation tool is a sequel to the earlier RPG Tsukuru. Data broadcast for this slotted cartridge also included the earlier-released RPG Tsukuuru - Super Dante.' FROM games WHERE igdb_id = 63501 ON CONFLICT (game_id, language_code) DO NOTHING;
