INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Command & Conquer', 'Experience the game that started it all! Enter a gritty, high-tech world and take advantage of electronic intelligence and covert surveillance to determine who reigns supreme. Join either the forces of the Global Defense Initiative (GDI) or the Brotherhood of Nod as you build bases, muster forces and dominate your enemies. All for the love of power. Play as the Brotherhood and obey the charismatic Kane’s every command or take control of GDI forces as they seek to save the world from Kane’s ambition. Gather Tiberium to produce tanks, infantry and more to decide the fate of the world.' FROM games WHERE igdb_id = 647 ON CONFLICT (game_id, language_code) DO NOTHING;
