INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('power-slave', 45972, '1995-10-27', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/dm9f40gve44lqczawqdt.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Power Slave', 'Tetsuya is a rather ordinary Japanese teenager, who prefers hanging out with his sweetheart Rika than going to school. His passion are 3D video games. The newest game machine which allows the player to completely submerge into the virtual world, modeled according to his desires, has captured his heart. But one thing is strange: lately, Tetsuya keeps seeing himself as a killer and rapist. Dreams begin to haunt him. Is this just a side-effect of the game, or does he have a dark side he knows nothing about? Or maybe the game took him to another world, which will from now on become part of his life?..' FROM games WHERE igdb_id = 45972 ON CONFLICT (game_id, language_code) DO NOTHING;
