INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Real Mahjong PIV + Aishou Shindan', 'Super Real Mahjong PIV + Aishou Shindan is a mahjong board game originally released for the 3DO Interactive Multiplayer. It offers traditional mahjong gameplay with additional modes and diagnostics for player matching and strategy analysis.' FROM games WHERE igdb_id = 347619 ON CONFLICT (game_id, language_code) DO NOTHING;
