INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Bizarre Adventures of Woodruff and the Schnibble', 'Woodruff and the Schnibble of Azimuth (marketed in North America as The Bizarre Adventures of Woodruff and the Schnibble) is a 1994 French adventure game developed by Coktel Vision. The game was created and written by artist Pierre Gilhodes, the creator of the Gobliiins series, of which Woodruff shares its visual style, gameplay and offbeat humor, though is not an official part of the Gobliiins series or canon.
