INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '21-Emon', 'Naturally a manga/TV anime tie-in, 21 Emon is one of those Japanese style board games that have never really made a big impact in the west. Four players (any combination of human and computer) take it in turns to roll dice and move around the isometric board, landing on various event squares. The ultimate aim is to build as many hotels as you can and make more loot than your opponents.' FROM games WHERE igdb_id = 38070 ON CONFLICT (game_id, language_code) DO NOTHING;
