INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chaos Control', 'Chaos Control, a super-production designed entirely on Silicon Graphics, takes you to the heart of a fantastic epic that blends cyberculture, virtual travel and manga graphics. At the controls of a space fighter, your dangerous missions will lead you into a unique spectacle with multiple, fantastic sets in full screen 3D vision.' FROM games WHERE igdb_id = 50320 ON CONFLICT (game_id, language_code) DO NOTHING;
