INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Circuit Racer', 'Circuit Racer (Known as "Speed Haste" in Europe) is a 3D arcade racing game with 2 types of vehicles, and different cars per type: the famous F-1 and the Stock Cars (best known as Formula NASCAR), each with different characteristics and maneuverability. The player can compete in the championship mode, covering all circuits with an increasing difficulty, but identical for both car types. The multiplayer mode offers split-screen racing or IPX-based sessions with up to 4 players.' FROM games WHERE igdb_id = 26656 ON CONFLICT (game_id, language_code) DO NOTHING;
