INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('chibi-maruko-chan-maruko-enikki-world', 92184, '1995-12-22', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coat9x.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4n93.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chibi Maruko-Chan: Maruko Enikki World', 'Momoko Sakura is an elementary school student who likes popular idol Momoe Yamaguchi and mangas. She is often called "Chibi Maruko-chan" due to her young age and small size. She lives together with her parents, her grandparents and her elder sister in a little town. In school, she has many friends with whom she studies and plays together everyday, including her close pal, Tama-chan; the student committee members, Maruo-kun and Migiwa-san; and the B-class trio: ''little master'' Hanawa-kun, Hamaji-Bu Taro and Sekiguchi-kun. This is a fun-loving and enjoyable anime that portrays the simple things in life.
