INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Deae Tonosama: Appare Ichiban', 'The Earth is in danger, the Tokugawa shogunate has been overrun by an extra-terrestrial evil force, and only two morons have the power to save the day. Play as either a daft French nobleman or an idiot Japanese lord and crush your foes with style. East meets west in this quirky but entertaining action game that unfolds across the world — and beyond!' FROM games WHERE igdb_id = 42390 ON CONFLICT (game_id, language_code) DO NOTHING;
