INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Panzer Dragoon', 'Panzer Dragoon is a rail shooter following the journey of Keil Fluge (unnamed in localized versions), a member of a hunting party who becomes the rider of a powerful blue dragon and joins it on its mission to stop a rival dragon from wreaking havoc on the world. The player moves an aiming reticle (representing the dragon''s laser and the rider''s gun) over the screen and shoots enemies while the dragon automatically flies through 3D environments on a predetermined track.
