INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Garfield: Caught in the Act', 'Odie scares Garfield while they are watching television and they fall on the TV, breaking it. Both characters attempt to repair it before Jon Arbuckle catches them; however, the thrown spare parts become an electronic monster known as the Glitch, transporting Garfield into the TV. Players take control of the titular cat across levels of varying themes on the television in order to defeat the Glitch and escape the TV.' FROM games WHERE igdb_id = 19736 ON CONFLICT (game_id, language_code) DO NOTHING;
