INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shadow Fighter', 'Shadow Fighter is a computer game for the Commodore Amiga, and Amiga CD32 developed by NA.P.S. team and published by Gremlin Interactive in 1994, and became one of the Amiga''s best fighting game offerings during its final years, competing at the time with the likes of Acclaim''s impressive home console ports of Midway''s Mortal Kombat franchise, and Team 17''s Body Blows.' FROM games WHERE igdb_id = 5524 ON CONFLICT (game_id, language_code) DO NOTHING;
