INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Undake30 SameGame Daisakusen Mario Version', 'Undake30 SameGame Daisakusen Mario Version is a Mario puzzle game released only in Japan for the Super Famicom. It was released as both a promotional cartridge and as a broadcast on the Satellaview. The game can be played with a standard joypad or the Super Famicom Mouse and is similar to the card game Monte Carlo. The game centers around a large playing field composed of a random arrangement of Mario heads, Coins, Yoshi Eggs, Fire Flowers, and Super Mushrooms. If two or more icons are connected, the player can move the cursor and double-click to make all the connected icons disappear. Once the entire grid is clear, the game ends.' FROM games WHERE igdb_id = 67024 ON CONFLICT (game_id, language_code) DO NOTHING;
