INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bishoujo Senshi Sailor Moon: Another Story', 'In the future Crystal Tokyo, a small band of discontent citizens have come together to form an rebel team of Senshi called the Oppositio Senshi, who feel that the Sailor Senshi and the Silver Crystal are the source of all of Earth''s past battles. Together with a mysterious woman named Apsu, they desire to twist time and change the destiny of the Earth.
