INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'BioForge', 'BioForge is an action-adventure game that was one of the first to feature fully textured 3D characters over pre-rendered backgrounds. In this unique cyber-thriller you collect items and solve mind-bending challenges to discover the secrets of your imprisonment and recover your lost identity. Fight against your robotic and human oppressors using a combination of melee weaponry and guns. Break out of your prison and show your foes what you’re made of. Half metal, half flesh, all vengeance!' FROM games WHERE igdb_id = 2213 ON CONFLICT (game_id, language_code) DO NOTHING;
