INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Elevator Action Returns', 'Elevator Action Returns, also known as Elevator Action II, is a 1994 run and gun arcade game developed and published by Taito. It is the sequel to Elevator Action (1983), featuring a much more gritty and realistic setting. Returns retains the elevator-based gimmick from the original, but expands the gameplay system and replaces the spy motif with a new scenario involving a paramilitary team fighting against a terrorist group.' FROM games WHERE igdb_id = 11729 ON CONFLICT (game_id, language_code) DO NOTHING;
