INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'KPatience', 'KPatience (executable kpat) is a all-in-one solitaire card games package made using the KDE libraries. It offers different patience-requiring solitaire games. It supports card deck themes and game themes and it has card animations if/when you win. KPatience comes with a very in-depth handbook which explains how to play the included solitaire games in case you never heard of them before.' FROM games WHERE igdb_id = 134532 ON CONFLICT (game_id, language_code) DO NOTHING;
