INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NFL Math', 'NFL Math is an educational game which aims to teach children about math. Each play is resolved by solving a math question which is always set as text problem. The goal is of course to answer as many questions as possible so the own team wins the match. The questions are divided into four categories (Number Sense, Geometry, Algebra and Statistics & Probability) and have four difficulty levels. The matches itself are either single or playoffs (a series of six matches).' FROM games WHERE igdb_id = 378029 ON CONFLICT (game_id, language_code) DO NOTHING;
