INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gundhara: Juudan Arashi', 'Gundhara - Juudan Arashi is a 2D top-down shooter, similar to Commando, Ikari Warriors or Bloody Wolf. The game has two heroes: Jerry and Jinn. Gameplay is simple and dynamic - the chosen hero shoots various enemies (like soldiers and robots) in the jungle and other location, and rescues hostages. A big boss awaits at end of each level. The heroes have guns, but can kick, upgrade their guns, and use special weapons.' FROM games WHERE igdb_id = 37336 ON CONFLICT (game_id, language_code) DO NOTHING;
