INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Battle Isle 2220: Shadow of the Emperor', 'Battle Isle 2220: Shadow of the Emperor is a hex-based strategy wargame released in 1995 for Windows 95, set 20 years after Battle Isle 2200. Players control Caro, leader of the Kais, in a civil conflict against the Drulls on planet Chromos, gaining support from the disembodied Emperor Punt Vassius who offers ancient military units in exchange for restoring his empire. The game features a 20-mission single-player campaign where players destroy enemy forces and capture objectives on hex-based maps.' FROM games WHERE igdb_id = 9032 ON CONFLICT (game_id, language_code) DO NOTHING;
