INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Terror TRAX: Track of the Vampire', 'Terror T.R.A.X.: Track of the Vampire is a cinematic adventure game. The player controls two T.R.A.X. agents, where T.R.A.X. stands for Trace Research Analyze and eXterminate: an organization founded in response to emergency 911 calls with a supernatural nature.' FROM games WHERE igdb_id = 71111 ON CONFLICT (game_id, language_code) DO NOTHING;
