INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'AV Jiu Ji Ma Jiang II', 'AV Jiu Ji Ma Jiang II (AV究極麻將2), also known as AV Kyuukyoku Mahjong 2 is an adult versus Mahjong game developed by Hummer Team and released by Ge De Industry Co. around 1995. It is a backport of Dial Q wo Mawase (ダイヤルQをまわせ！), an unlicensed Sega Mega Drive title.' FROM games WHERE igdb_id = 247306 ON CONFLICT (game_id, language_code) DO NOTHING;
