INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Linda Cube', 'Linda Cube is an esoteric JRPG that combines elements of psychological horror with monster collection. Neo Kenya is the name of a world that is in danger of being completely annihilated by an asteroid. The armies of Neo Kenya have searched for every conceivably way to prevent the coming catastrophe. When the inhabitants of the world turn to a dark god, their prayers and nightmares come true. Originally released for PC, Linda³''s shockingly violent scenes earned it one of the few “18+” ratings on the system.' FROM games WHERE igdb_id = 94898 ON CONFLICT (game_id, language_code) DO NOTHING;
