INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gex', 'Enter your television to defeat the evil Rez by collecting remotes to open worlds inside your tv. You are a gecko with all the usual platform hero skills such as jump, fire and close range attack, but also suction cups to help you scale walls, a tongue to pick up those tricky to get power-ups and plenty of wise-cracks to keep you amused. Use them all to make your way through TV land searching for the remotes, collecting pickups, power-ups and killing TVs.' FROM games WHERE igdb_id = 4309 ON CONFLICT (game_id, language_code) DO NOTHING;
