INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fort Boyard: The Challenge', 'Fort Boyard: The Challenge is an adventure, action/reflex, puzzle video game for MS-DOS, created and published by Microïds in 1995. This game will transport you into the heart of a foreboding island fortress and one of the world''s most celebrated TV game shows. 1 to 6 players per team meet the challenge of the Fortress and its inhabitants. Each puzzle is prefaced by a required skill, allowing a team of players to select the most skilled from the ranks. These skills are Clever, Tough, Agile, Sharp, Strong, and Captain. Puzzles are chosen randomly so no game plays exactly the same twice.' FROM games WHERE igdb_id = 388268 ON CONFLICT (game_id, language_code) DO NOTHING;
