INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'IndyCar Racing II', 'The fourth Papyrus racing game is the sequel to the 1993 IndyCar Racing. It uses many of the improvements which were introduced in NASCAR Racing. There are fifteen tracks in total, and the major features are 640x480 SVGA graphics, multiplayer support for two players, pit telemetry data for realism, interactive driving schools, enhanced artificial intelligence, in-game communication with the pit crew supporting speech recognition technology, and digital stereo sound.
