INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Majuu-ou: King of Demons', 'Majuu-ou is a side-scrolling platformer for the Super Nintendo, taking influences from Castlevania and Contra. You play as Abel, intent on rescuing his daughter from the depths of Hell. As you defeat certain bosses, they will drop large, color changing gems. Pick up the gem, and you''ll transform into either a red Harpy, a blue Dragon, or a green Lizard, depending on what color it is when you pick it up. Each demon type has its own special attacks.' FROM games WHERE igdb_id = 38112 ON CONFLICT (game_id, language_code) DO NOTHING;
