INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Manchester United Championship Soccer', 'The game was released at the time when Manchester United was starting to dominate the English football scene. All the teams from the 1994–95 FA Premier League are represented. All-star teams and various European clubs that participated in the European competitions from the 1994/95 season are also included. During the gameplay the player can choose two type of views: top down and isometric view of the pitch.' FROM games WHERE igdb_id = 42503 ON CONFLICT (game_id, language_code) DO NOTHING;
