INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('wings-of-glory', 46717, '1995-02-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5wvk.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wings of Glory', 'Wings of Glory is one of the relatively few World War 1 flight simulators. It is played in 1st person, with 3rd person camera options and uses Origin''s RealSpace Engine. In the main campaign, players start as a fresh rookie pilot, newly transfered to England. Players can have conversations with other pilots,check the kill board for the entire squadron or commence the next mission. Missions begin with a briefing explaining the objectives and then players are put in the front seat of their aircraft. They must take off, reach the appropriate waypoints, perform the objective and return home to land. All planes have a machine gun, of varying capacities , which fires in front of the plane. Some planes are also able to carry bombs. There is no radar or other detection method on the planes, so players must be alert to oncoming enemies.' FROM games WHERE igdb_id = 46717 ON CONFLICT (game_id, language_code) DO NOTHING;
