INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jagged Alliance', 'Jagged Alliance combines turn-based strategy and role-playing elements in a gripping mercenary-themed adventure. Set on the fictional island of Metavira, players are tasked by scientist Jack Richards and his daughter Brenda to reclaim control of the medicinal Fallow trees from the villainous Santino. Players must recruit and manage a team of mercenaries from a diverse roster of 60 unique characters, each with distinct personalities, skills, and voiced dialogue.
