INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mario''s Game Gallery', 'Mario''s Game Gallery is a collection of board games, in which you play with Mario. He talks to you, playing Checkers, Go Fish, Dominoes, Backgammon and Yacht. The games all play similarly to their real world counterparts, featuring pieces based on the Mario universe. Mario''s Game Gallery is the first game in the series to feature Charles Martinet as Mario''s voice actor, who has since gone on to act as Mario''s voice actor in all games that give Mario a voice since.' FROM games WHERE igdb_id = 21624 ON CONFLICT (game_id, language_code) DO NOTHING;
