INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Patchwork Girl', 'Patchwork Girl tells the story through illustrations of parts of a female body that are stitched together through text and image. The narrative of the story is divided into five segments, titled: "a Graveyard", "a Journal", "a Quilt", "a Story", and "& broken accents." The goal of the piece is to not only make the reader realize the structure of the Patchwork Girl as a whole but also realize all the pieces that must be "patched" together in order to create one unified structure.' FROM games WHERE igdb_id = 180242 ON CONFLICT (game_id, language_code) DO NOTHING;
