INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'X-Men: Gamesmaster''s Legacy', 'X-Men: Gamesmaster''s Legacy is an action game released in 1995 on the Game Gear. The game starts off with Cyclops and Storm as playable X-Men, although Wolverine, Gambit, Rogue, Bishop, Jean Grey, and Cable can be later unlocked. It is loosely based on the "Upstarts" and "X-Cutioner''s Song" storylines that took place in the comics. It is the sequel to the original X-Men Game Gear game.' FROM games WHERE igdb_id = 19938 ON CONFLICT (game_id, language_code) DO NOTHING;
