INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('meltylancer-the-melting-pot-police', 340399, '1995-06-23', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9on4.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scwbc3.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Meltylancer: The Melting Pot Police', 'MeltyLancer is a life simulation game similar to -- and by the same designers as -- Graduation, in which the player is tasked with training a squad of six young Tokyo Eastern Metro Police recruits, called Lancers. The main core of the game is determining each Lancer''s weekly schedule: which days are they on patrol, which days on standby, and which days do they have off? After the general schedule is determined, the player meets with each Lancer to speak with them directly, determining specific actions they''ll take that week; whether they spend a day training, exercising, or getting some much-needed rest will affect their stats and ability to complete missions. While on patrol or on special missions, battles may occur, which can be partially controlled with a handful of commands but mostly play out automatically. Each of the six Lancers has their own abilities, personalities, and specialties.
