INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rocman X', 'Rocman X (洛克人X) (also known as Thunder Blast Man) is an unlicensed game created by Sachen, released on the Famicom and NES sometime in the 90''s and also sometime later for the Game Boy Color. The NES and English Game Boy Color versions were released as Thunder Blast Man, the Chinese version of the GBC game released as 洛克人X金 (Rockman X Gold), and one of the NES versions'' label calls it Thunder Blaster Man.' FROM games WHERE igdb_id = 247412 ON CONFLICT (game_id, language_code) DO NOTHING;
