INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('heisei-tensai-bakabon-susume-bakabons', 70877, '1995-07-07', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cobc2g.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar555g.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Heisei Tensai Bakabon: Susume! Bakabons', 'Heisei Tensai Bakabon: Susume! Bakabons is a competitive falling-block puzzle game based on the 1990 animated series Heisei Tensai Bakabon. Pairs of blocks in four colors drop from the top of the screen, and the goal is to line up two or more blocks of the same color, with another pair of a different matching color at either end. Any blocks on top of the ones cleared will fall into the open space, potentially comboing together into chains. Clearing multiple sets of blocks in a combo or chain will send garbage blocks to the opponent''s playfield, and also charge up a super move that triggers automatically at a certain threshold which can clear a large number of blocks from the playfield.
