INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yogho Yogho spel', 'Yogho Yogho spel is a platform game where the player takes the role of a boy who likes the Dutch yoghurt drink Yogho Yogho. In every level the protagonist has to find one or more objects and bring them to someone or something. Bonus levels full of fruits can be played in between to help the player reach a higher score. Lives come in the form of dreams and hit points can be replenished by drinking a glass of Yogho. Locked doors can be unlocked with keys found around the map.' FROM games WHERE igdb_id = 78953 ON CONFLICT (game_id, language_code) DO NOTHING;
