INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sylvan Tale', 'Sylvan Tale follows the typical action-adventure game formula: The player controls a character who must solve puzzles, fight enemies, and talk to non-player characters in order to acquire special powers and items that will allow him to unlock new areas of the game world and solve the puzzles within. While the player may revisit areas, the game progresses in an essentially linear fashion, as each area can only be accessed if Zetts(the player character) has acquired a specific item or ability from the previous area.' FROM games WHERE igdb_id = 19691 ON CONFLICT (game_id, language_code) DO NOTHING;
