INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Goal! Goal! Goal!', 'A soccer game with all the right ingredients, skill, flair, passion, and of course, GOALS! With 28 national teams to choose from, compete in a tournament to become the best soccer nation in the world. Get past the opening group stage and go on to a round-robin elimination stage where failure is not an option. To help you on your way, hold down the shoot button until the power bar fills up and you can do a POWERFUL SUPER SHOT!' FROM games WHERE igdb_id = 39549 ON CONFLICT (game_id, language_code) DO NOTHING;
