INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hameln no Violin Hiki', 'Hameln no Violin Hiki is a platform game based on the manga/anime series of the same name. You play the role of Hamel who is an adventurer with a violin as his trusty weapon. Hamel and his mascot Oboe arrives at Staccato, a small town attacked by monsters, and drives them away with his power. Impressed, a cute little girl named Flute decides to go with Hamel in order to find and destroy the evil power behind the attacks.' FROM games WHERE igdb_id = 38365 ON CONFLICT (game_id, language_code) DO NOTHING;
