INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Stargate', 'Warp through the Stargate to an intergalactic dimension of non-stop action, danger and adventure! Face a hostile and unknown world in over 30 missions. From the village of Naganda to Ra''s pyramid spacecraft, you''re armed with an arsenal of weapons and incredible alien fire power. It''s up to you to defeat the evil ruler Ra and unlock the mystery of the Stargate! It will take you a million light years from home... but can you find your way back?' FROM games WHERE igdb_id = 10162 ON CONFLICT (game_id, language_code) DO NOTHING;
