INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zaxxon''s Motherbase 2000', 'This 32X-exclusive sci-fi shooter is similar gameplay-wise to Sega''s arcade game Zaxxon. The graphics consist of a diagonally scrolling playfield which creates a pseudo 3D environment. The backgrounds are drawn using 2D scrolling planes, but the enemy and ship objects are drawn using 3D flat-shaded polygons.
