INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tecmo Super Bowl III: Final Edition', 'A late entry in what was once the premiere football simulation, TSB III has updated rosters and teams for the 1994-1995 season and is licensed by both the NFL and the Players group. This game features real NFLP players and photos, the real NFL schedule, and weekly standings. You can change defensive and offensive formations, create your own Pro Bowl, fake punts and field goals, go for the two point conversion, and call audibles. Updates to the game itself include new cinema screens, superstar mode, free agency system, improved graphics, larger field simulation, passing modes, and improved speech and music.' FROM games WHERE igdb_id = 42445 ON CONFLICT (game_id, language_code) DO NOTHING;
