INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Secret of Evermore', 'Secret of Evermore is another famous RPG developed and released by Square in 1995. A day at the movies for a young boy & his dog turns into an adventure that spans across several different time periods and locations, on their journey they discover the Secret of Evermore and find their way home. Produced by the North American branch of Square, Evermore''s soundtrack would be the first major work by Jeremy Soule, the famed Elder Scrolls composer.' FROM games WHERE igdb_id = 1359 ON CONFLICT (game_id, language_code) DO NOTHING;
