INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('nba-action-95-starring-david-robinson', 4551, '1995-06-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5oyg.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/uwtg41krktmrxapyjid9.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NBA Action ''95 starring David Robinson', 'It''s time once again to hit the hardwood with The Admiral and the rest of the NBA in NBA ACTION ''95 STARRING DAVID ROBINSON. You''ll find 27 teams with full rosters at your service, so you can throw down with your favorite NBA superstars. The game is played from a unique Fast-Breaking View, so you won''t miss a second of the high-flying action as you make a coast-to-coast run for an easy lay-up. You can play a Full Season, go straight to the Playoffs, or even jump right to the NBA Finals and see if you''ve got the goods to bring home the championship. Marvelous Marv Albert calls all the action, and you can design and run up to 40 original plays. Break out the high-tops and get ready for the intense action of the NBA with NBA ACTION ''95 STARRING DAVID ROBINSON.' FROM games WHERE igdb_id = 4551 ON CONFLICT (game_id, language_code) DO NOTHING;
