INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('sd-gundam-g-next', 38324, '1995-12-22', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9dcb.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SD Gundam G Next', 'SD Gundam G Next is a Strategy game, developed by Japan Art Media (JAM) and published by Bandai, which was released in Japan in 1995. It is a Satellaview-compatible Slotted Cartridge game. The game was playable on its own without any data packs, it was playable in conjunction with 8M Pack data downloaded via the BS-X cartridge, and it could also be used together with the separately released Write-protected memory pack, Unit & Map Collections (SHVC-039).' FROM games WHERE igdb_id = 38324 ON CONFLICT (game_id, language_code) DO NOTHING;
