INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Head-On Soccer', 'In this isometric football game, 51 national teams are represented to play in two game modes: Exhibition and Tournament (a series of seven games on four continents, with a final against the World All-Stars), with the ability to set time, difficulty level, see cutscenes after goals and if players are free to kick each other around without (many) fouls.' FROM games WHERE igdb_id = 19758 ON CONFLICT (game_id, language_code) DO NOTHING;
