INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('adventures-in-letterland-with-jack-and-jill', 84372, '1995-09-10', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3zg5.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Adventures in Letterland With Jack and Jill', 'Adventures in Letter Land with Jack & Jill is an animated storybook game with the nursery rhyme characters Jack, Jill, and Mother Goose. This game doubles as a storybook and a game, with mini-games found on each page. In Parachute Letters, players must match the letter with the one Mother Goose is carrying, In ABC Land, you must match multiple different letters in a row. In Conveyor Belt Words, you must complete the word given by finding the correct letter on the convener belt. In Robot Designer, you can create a unique robot by using different parts, and it will even dance for the player. On Cake Island, you must arrange fallen gumdrops in alphabetical order. On the Sunken Letter Ship, you must match the capital letter with its lowercase form. Finally, you are able to make your own story on the last page of the book. There is also a butterfly coloring book on the 2nd page. Some activities have several levels of difficulty, and the game primarily teaches alphabet and reading skills.' FROM games WHERE igdb_id = 84372 ON CONFLICT (game_id, language_code) DO NOTHING;
