INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ganbare Goemon: Kira-kira Douchuu - Boku ga Dancer ni Natta Wake', 'Fourth title in the Ganbare Goemon series of platform/adventure games which cast you as the heroic Goemon and his gang of wacky adventurers as he fights evil all over Japan. This sequel however, takes the action to outer space as the gang attempts to rescue Goemon Impact (Goemon''s giant mecha) from a strange planet.
