INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chronomaster', 'You are Korda, the Chronomaster. You must re-start time and right the wrongs of a war-plagued past in this epic quest for vengeance. Journey through man-made "pocket universes" full of cyborgs, pirates and witches who provide deadly puzzles. It''s up to you to return justice to the stars.' FROM games WHERE igdb_id = 189291 ON CONFLICT (game_id, language_code) DO NOTHING;
