INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Ultimate Doom', 'The complete megahit game that set the world afire. Plus All-New Episode IV: Thy Flesh Consumed. The demons came and the marines died. Except one. You are the last defense against these hell-spawned hordes. Prepare for the most intense mutant-laden, blood-splattered action ever! The texture-mapped virtual world is so real, you don''t just play Doom - you live it.' FROM games WHERE igdb_id = 10192 ON CONFLICT (game_id, language_code) DO NOTHING;
