INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('worms', 9331, '1995-10-31', 80, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1xqn.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arjzg.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Worms', 'Worms combines the best elements from the very best games ever created. It requires great thought, strategy and elements of sheer outrageous fortune. It provides the players with an almost infinite range of playing possibilities. It does take a little while to get into the swing of things however and despite everyone’s insistence that you should not need to read a game manual to be able to play it. Worms can be played by 1-16 players at the same time - it’s a turn based game so you`ll only need one machine - but prepare to be at odds with your loved ones, get ready to shout abuse at your best friend and be willing to exact unadulterated terror on those who plot to hurt your worms.
