INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('mazer', 4317, '1995-06-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3yqc.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mazer', 'In Mazer, the player can choose from one of four soldiers tasked with freeing Earth from the oppressive rule of an alien race known as the Semag-Resal, who have a network of bases located all over Earth. To make matters worse, they have developed cyborgs that can perfectly mimic human beings that can infiltrate their rebel hideouts and exterminate them.' FROM games WHERE igdb_id = 4317 ON CONFLICT (game_id, language_code) DO NOTHING;
