INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('eco-east-africa', 71318, '1995-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7g2u.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Eco East Africa', 'Eco East Africa is a managerial simulation with educational elements, in which the player takes the role of a warden of Ethemba, a fictional Kenyan wildlife park. The player has to raise funds for managing the park, hire staff, build tourist stations, face various ecological problems, etc. The player must learn and understand environmental habits of the animals, and pay attention to their particularities when dealing with them. Poachers will often enter the park, and it is the player''s job to keep them away. In addition, a "tourist" mode allows the player to walk in the park and observe the behavior of the animals.' FROM games WHERE igdb_id = 71318 ON CONFLICT (game_id, language_code) DO NOTHING;
