INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sensible World of Soccer: European Championship Edition', 'A "sequel" of sorts to Sensible Software''s 1996 Sensible World of Soccer. Based on the teams that played in Euro ''96 tournament, SWOS: European Championship Edition sports new features that make the game even more addictive than SWOS, including the ability to pull off looping headers and curved passes, trial players, international management, and more charming cartoony graphics such as animated crowd and goal celebrations. The PC version of SWOS: ECE features digitized match commentary and funny animation sequences.' FROM games WHERE igdb_id = 79251 ON CONFLICT (game_id, language_code) DO NOTHING;
