INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Oceans Below', 'Adjust your air flow and check your pressure gauge. Splash! The water is warm and visibility good. Slowly you descend into an exotic undersea world, the water teeming with colourful fish and spectacular reef formations. Today you''ve decided to explore a sunken ship. Tomorrow maybe you''ll slice through the water on a Manta Ray, or dare to face a Great White Shark! Oceans Below contains over 200 video segments and over 125 photographs, covering underwater animal and plant life, plane wrecks, ship wrecks and more.' FROM games WHERE igdb_id = 37124 ON CONFLICT (game_id, language_code) DO NOTHING;
