INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Island Casino', 'Check-in to the El San Juan Hotel and Casino and hit the tables for 25 of the world''s most popular casino games! Or learn to play with step-by-step, easy-to-understand instruction. Brilliant graphics and sophisticated gameplay put you right in the center of the non-stop casino action, and let you feel the thrill of hitting it big with the most complete and authentic gambling experience available on CD-ROM. It''s your Virtual Vacation- and it''s only a mouse-click away- Island Casino!' FROM games WHERE igdb_id = 262406 ON CONFLICT (game_id, language_code) DO NOTHING;
