INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Living Books: Dr. Seuss''s ABC', 'The magic of Dr. Seuss''s popular books comes to life in this fun-filled introduction to the ABCs of reading. Click on a noun and see its picture. Click on a verb to see an action. It''s easy for kids to replay a favorite part, skip ahead and learn more than 600 different words while they play. Introduce your children to Dr. Seuss''s wondrous world today.' FROM games WHERE igdb_id = 134447 ON CONFLICT (game_id, language_code) DO NOTHING;
