INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chop Suey', 'Chop Suey is a point-and-click adventure game intended for girls aged 7–12, featuring a colorful interactive storybook. The player clicks on the map of the town to explore buildings, houses and roads. Whenever everything in an area has been examined, the cursor changes to a moon, and a pointing finger appears on the screen to lead to another location.' FROM games WHERE igdb_id = 47297 ON CONFLICT (game_id, language_code) DO NOTHING;
