INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pantsylvania', 'The Gigglebone Gang: Pantsylvania is an educations game. The gang visits the kingdom Pantsylvania where they teach children various facts, bits of fiction, various bouts of craziness. and can enter ten destinations, e.g. a restaurant, the castle or a school. Each location has five activities which are reached by clicking on one of the gang members or the king.' FROM games WHERE igdb_id = 64373 ON CONFLICT (game_id, language_code) DO NOTHING;
