INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kanzen Chuukei Pro Yakyuu Greatest Nine', 'Greatest Nine began on the Sega Saturn in 1995. New releases in the series stopped for a while after 1998. However, it was revived in 2002 on the Game Boy Advance (GBA). This Game Boy Advance version has developed by Smilebit (absorbed by Sega in 2004), behind the Motto Pro Yakyuu Team o Tsukurou! franchise.' FROM games WHERE igdb_id = 272901 ON CONFLICT (game_id, language_code) DO NOTHING;
