INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Slam Dunk: Kyougou Makkou Taiketsu!', 'Slam Dunk: Kyogo Makko Taiketsu! (Champion Front Showdown!) is a five-on-five basketball game based on the anime and manga created by Takehiko Inoue. Following the story, starting from the first exhibition matches, the player can take control of either a single player or the whole Shohoku team in an arcade-style basketball game. The game uses a side-view for the center court, and zooms in for a head-on view when near the basket. There is also an exhibition mode for up to five players, where six different school teams from the series are available for play.' FROM games WHERE igdb_id = 45640 ON CONFLICT (game_id, language_code) DO NOTHING;
