INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Amazing Spider-Man: Lethal Foes', 'The Amazing Spider-Man: Lethal Foes is an action game released in 1995 for the Super Famicom, showcasing the Marvel Comics character Spider-Man. This game, launched in Japan, seems to have drawn its title inspiration from the 1993 limited series "The Lethal Foes of Spider-Man." However, it''s important to note that the game''s storyline diverges from that of the comic, despite incorporating various adversaries of Spider-Man.' FROM games WHERE igdb_id = 42403 ON CONFLICT (game_id, language_code) DO NOTHING;
