INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Twinkle Knights', 'Twinkle Knights, is a card-based fighting game where your female opponents just happen to lose their clothes bit by bit if you win a round. The game extends its life by making each fight 5 rounds, and the computer manages to pull some good cards on you when you least expect it, extending its lifespan a bit.' FROM games WHERE igdb_id = 39016 ON CONFLICT (game_id, language_code) DO NOTHING;
