INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Quarterback Attack with Mike Ditka', 'Quarterback Attack with Mike Ditka is a full motion video game released for the Sega Saturn. As the name may suggest, it is themed around the sport of American football; specifically, it uses FMV to show what happens in a football game every time you, as the quarterback, do something. It was only released in North America.' FROM games WHERE igdb_id = 176692 ON CONFLICT (game_id, language_code) DO NOTHING;
