INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'PC Mus', 'The game is a simulator of mus, a card game of Spanish origin with more than two hundred years of history that is widely played in countries such as Spain, Argentina, Chile, Colombia, Mexico and in certain regions of southern France. Although the game may seem a bit cheap due to its graphics, the truth is that the player can play a game of mus with each and every one of its moves and rules: bets, bluffs, signals, etc.' FROM games WHERE igdb_id = 327335 ON CONFLICT (game_id, language_code) DO NOTHING;
