INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'PO''ed', 'PO''ed is a first-person shooter with two simple objectives: escape the alien homeworld and kick lots of butt! There are 25 levels in all, each with a challenging array of horrific aliens to destroy, switch puzzles to solve, and platforming elements. Ox can either walk throughout the levels or utilize an ultra-powerful jetpack; use the latter in moderation as it''s an important, yet limited tool.' FROM games WHERE igdb_id = 4327 ON CONFLICT (game_id, language_code) DO NOTHING;
