INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jikki Pachi-Slot Simulator Vol. 1', 'Simulating the mechanics and rules of a pachislot machine, the game can be played in the strategy, battle or introductory modes. The player can choose from a selection of six different machine designs, which are based on real-life machines. The player configures the options token bets and paylines in a separate menu before playing the on the slot machine. Each slot row can be stopped at the press of a controller button.' FROM games WHERE igdb_id = 254450 ON CONFLICT (game_id, language_code) DO NOTHING;
