INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Proliferation', 'Proliferation is a formerly-shareware World War III strategy game for up to six players, human- or computer-controlled. Nuclear weapons, both tactical and strategic, have proliferated throughout the nations of the world, and the five largest nuclear powers, after failed efforts to militarily compel the smaller nuclear-armed nations to disarm, have plunged the world into global war. You take the role of one of the five major nuclear powers, seeking to extend your sphere of influence and eventually become the dominant power.' FROM games WHERE igdb_id = 79705 ON CONFLICT (game_id, language_code) DO NOTHING;
