INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Galt-Rio Maximum Position', 'A shoot-''em-up with more dialogue than most, just don''t run into your wingman in mid-exposition... the graphics are all pretty nice, although it seems odd all the shots are simple yellow squares. Movement is via the arrow keys, X shoots, while Z purchases whatever power-up is available, Gradius-style, from the bar below.' FROM games WHERE igdb_id = 210773 ON CONFLICT (game_id, language_code) DO NOTHING;
