INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Alien Odyssey', 'You were just taking a regular old trip to an alien planet, when a big war happened to break out. Now, you''re caught in the midst of a raging battle between the planet''s native life form and a race called the Dak. The only chance you have of escaping safely is by helping the locals win the fight, so suit up, and come out with your guns blazing. This long-form adventure has no shortage of action to keep you on the edge of your seat, the puzzles are many, and the graphics are before their time.' FROM games WHERE igdb_id = 50325 ON CONFLICT (game_id, language_code) DO NOTHING;
