INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Eisei Meijin', 'Eisei Meijin is a digital conversion of the traditional Japanese board game Shogi for one or two players, and the first game in Konami''s long-running Shogi series to come to console. In addition to standard play against the computer or a second player, it includes the ability to record and play back matches, and even includes playable records of several historical Shogi matches from the Edo era. Also included are a board edit mode and a tool that automatically solves Tsume Shogi problems.' FROM games WHERE igdb_id = 268639 ON CONFLICT (game_id, language_code) DO NOTHING;
