INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wolfsbane', 'Wolfsbane is predominantly an adventure game, which plays for the most part similarly to point-and-click examples of the genre, despite the unusual side-scrolling perspective. The player must explore the town, talk to its inhabitants, and gather information and items in order to solve the mystery. The game utilizes a branching dialogue system. It also has action elements, present in the sporadic combat and a health meter for Axel.' FROM games WHERE igdb_id = 171101 ON CONFLICT (game_id, language_code) DO NOTHING;
