INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Power Drive Rally', 'Fueled by a nitro-burning, 64-bit graphics engine, PowerDrive Rally delivers the sights, sounds and the chaotic intensity of pure Rally racing. You''ll actually see the skid marks and icicles fly as you tear across the Italian countryside. Hear the gears grind and your navigator sneer as you rip through the Arizona desert. Feel the heart palpitations and adrenaline overload as you bury the needle along the dust-choked African plains.' FROM games WHERE igdb_id = 79089 ON CONFLICT (game_id, language_code) DO NOTHING;
