INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'RBI Baseball ''95', 'This version is an updated follow-up to the R.B.I. series. Many of the same features from other baseball games are present and has three different game modes to choose from: exhibition, playoff, and home run derby, but what makes this version different from the others is a lack of MLB license, though it does feature a MLBPA license with top players of the time such as Roger Clemens, Otis Nixon, Bobby Larkin among many others.' FROM games WHERE igdb_id = 45876 ON CONFLICT (game_id, language_code) DO NOTHING;
