INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kuro no Ken', 'Kuro no Ken is a rather standard Japanese-style RPG with all the familiar ingredients: top-down locations, navigation on the world map, random enemies, turn-based combat, automatic leveling up, etc. The battles are viewed from a third-person perspective, using much larger character sprites than during exploration. Shinobu and Kayes can use physical attacks or magic spells (learned automatically when leveling up), which deplete MP.' FROM games WHERE igdb_id = 178243 ON CONFLICT (game_id, language_code) DO NOTHING;
