INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tintin in Tibet', 'Re-live the adventures of Tintin on the search for his friend Chang. What happened to Chang after the crash of the DC3 on the way to Kotmondu? Set off with Tintin to Tibet where all along your exciting journey you''ll find vital items to aid your progress and interrogate the locals for helpful advice. You''ll face many a danger as you examine the aeroplane wreck, climb on steep rock walls and meet the legendary Yeti.' FROM games WHERE igdb_id = 46493 ON CONFLICT (game_id, language_code) DO NOTHING;
