INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Africa Trail', 'Africa Trail is an educational computer game developed by MECC and published by The Learning Company. The gameplay resembles that of MECC''s other "Trail" games, in which players must prepare for a long journey, choose their traveling companions, and make it safely to their destination. In Africa Trail, players must travel across Africa via bicycle. The game includes a Multimedia Resource Tool to allow players to make their own journal and presentation of the journey.' FROM games WHERE igdb_id = 93262 ON CONFLICT (game_id, language_code) DO NOTHING;
