INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Necrobius', 'In development circa 1995, Necrobius was supposed to be a surreal humorous adventure through the brain of a scientist. The demo appeared in July 1995 issue of PC Gamer, but the game itself was subsequently cancelled by the publisher MicroProse. It was ultimately released as freeware in 2014 by the developer Daniel Auld himself.' FROM games WHERE igdb_id = 178181 ON CONFLICT (game_id, language_code) DO NOTHING;
