INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shin Togenkyo', 'Shin Togenkyo ("New Togenkyo", where Togenkyo refers to a mythical garden from Japanese folklore) is a game from that offers players advice and fortune telling by taking some personal details and divining various predictions from that input. The game is heavily reliant on Japanese script, and offers little in the way of visuals besides the occasional icon used to represent the player''s status. It also offers a rudimentary slot machine for players to try their luck in a different manner.' FROM games WHERE igdb_id = 38252 ON CONFLICT (game_id, language_code) DO NOTHING;
