INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cluedo: The Mysteries Continue', 'Cluedo, known as Clue in the USA, is a popular board game with a murder mystery theme. The CD-i version makes full use of Digital Video to present the viewer with a challenging game. By interviewing real characters and using a process of deduction the viewers must play against each other to find the murderer, the murder weapon and the murder room, and correctly accuse the culprit.' FROM games WHERE igdb_id = 45936 ON CONFLICT (game_id, language_code) DO NOTHING;
