INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Twin Brats', 'Twin Brats is 2D action game - a clone of Lady Bug or PacMan. The player controls a character who looks like a child in diapers. He must collect all dots from the arena, and avoids enemies (and deadly skulls). He can use otating doors to escape from enemies or trap them. The game is adult themed - a picture of a naked woman shows up after each passing level (something that the new IP owner, Piko Interactive, removed from the Evercade VS release.)' FROM games WHERE igdb_id = 289132 ON CONFLICT (game_id, language_code) DO NOTHING;
