INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Scholastic''s The Magic School Bus: Space Exploration Game', 'Based on the PBS kids program, The Magic School Bus along with Ms. Frizzle and her companion Liz takes the player throughout the solar system one planet at a time to learn about them while exploring each one. Along the way, players will be transported on the bus on their way to the next planet where they can take photos of the planets, their moons, stars, among many other things they can see. Along the way they will encounter puzzles they have to solve in order to advance using the facts they have learned through their planetary visit and can also build their own solar system in any way they choose.' FROM games WHERE igdb_id = 46280 ON CONFLICT (game_id, language_code) DO NOTHING;
