INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Amusement Planet Phantasmagoria', 'Amusement Planet Phantasmagoria is an interactive multimedia game is set in the same world as Shigeru Tamura''s book Phantasmagoria. Players freely explore the beautiful and mysterious planet Phantasmagoria, seeing the sights and interacting with the people at their own pace. Following an introduction by planetary researcher Dr. Hoop, the game begins with a rotating view of the planet which players can use to pick their first destination. Each location is a self-contained animated scene, which players can interact with by clicking people and things. Clicking at the edge of the screen lets the player move in that cardinal direction, travelling the world destination by destination.' FROM games WHERE igdb_id = 133627 ON CONFLICT (game_id, language_code) DO NOTHING;
