INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cartoon Toolbox Starring Felix the Cat', 'Big Top''s Cartoon Toolbox Starring Felix the Cat lets you put your creativity in motion with the most amazing animation program yet! Featuring the beloved and wacky Felix the Cat, this award-winning CD-ROM provides kids and adults a fun and easy way to create their own professional looking cartoons.' FROM games WHERE igdb_id = 144002 ON CONFLICT (game_id, language_code) DO NOTHING;
