INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dekitate High School', 'Dekitate High School is a Super Famicom video game that was released to an exclusively Japanese market in 1995 and was considered to be the first "high school simulation" video game to be released for the Super Famicom. Famed Japanese illustrator Nishiki Yoshimune would draw the cover art for the game while the actual character design was done by the in-house staff at C-Lab.
