INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'I.M. Meen', 'I.M. Meen is a 1995 educational video game that runs on DOS, designed to teach grammar to children. In this game, the player must walk around a labyrinth, rescuing children and defeating monsters. The educational aspect of the game comes in the form of "scrolls", writings of I.M. Meen in which the player must correct the grammatical mistakes in order to rescue the children.' FROM games WHERE igdb_id = 84281 ON CONFLICT (game_id, language_code) DO NOTHING;
