INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lincity', 'Lincity is a free and open-source software construction and management simulation game, which puts the player in control of managing a city''s socio-economy, similar in concept to SimCity. The player can develop a city by buying appropriate buildings, services and infrastructure. Its name is both a Linux reference and a play on the title of the original city-building game, SimCity, and it was released under the GNU General Public License v2.' FROM games WHERE igdb_id = 46721 ON CONFLICT (game_id, language_code) DO NOTHING;
