INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hansel and Gretel and the Enchanted Castle', 'The classic children''s fairy tale in cartoon format with puzzles to solve, and all the drama, realism and music of a feature film. Hansel and Gretel are abandoned in a forest where a Wicked Witch takes them prisoner. They must figure out how to escape, lest she put them in her oven! Two levels of difficulty, and it can also be used as a language learning tool (English, Spanish, German, French, and Japanese), since you can pick one language for dialogue and another for the objects named (or both the same).' FROM games WHERE igdb_id = 46641 ON CONFLICT (game_id, language_code) DO NOTHING;
