INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cryptograms', 'In this game the player is presented with a well known word or saying in which all the letters have been replaced by another, for example all the A''s may have been replaced by G''s, the B''s by Z''s and so on. The object of the game is to decode the phrase.' FROM games WHERE igdb_id = 116955 ON CONFLICT (game_id, language_code) DO NOTHING;
