INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Big Red Adventure', 'The Big Red Adventure is a PC adventure game in which you once again are Doug Nuts, an international thief. This time you''re off to steal the royal crown of the Russian Czars. In order to get it you''ll of course need to perform different little tasks, that don''t seem to have any connection with your main objective. Well, you finally get into the museum and can already taste the crown in your hand, when the real adventure begins.' FROM games WHERE igdb_id = 12404 ON CONFLICT (game_id, language_code) DO NOTHING;
