INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Congo the Movie: Descent into Zinj', 'Congo is an adventure game adapted from the 1995 movie of the same name. The plot revolves around a search for a diamond that presumably have power enough to change the world of telecommunications as we know it. On a mission issued by Travis, the head of TraviCom, you are sent in contemporary Congo in order to recover the diamond and find out what has happened to another expedition led by Dr. Karen Ross.' FROM games WHERE igdb_id = 99690 ON CONFLICT (game_id, language_code) DO NOTHING;
