INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'I-War', 'I-War is a 3D virtual reality tank game. In each of the 21 levels, you must find all the data pods and make your way to the exit. Enemy tanks, turrets, and bombers stand in your way, as well as occasional traps or locked doors controlled by hidden switches. Levels are divided into simple, enclosed rooms, linearly connected by one-way teleporters.' FROM games WHERE igdb_id = 40820 ON CONFLICT (game_id, language_code) DO NOTHING;
