INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jurassic Park Part 2: The Chaos Continues', 'A year has passed and the dinosaurs are still alive in Jurassic Park 2: The Chaos Continues. Take control of Dr. Grant as he returns to Jurassic Park and battles the dinosaurs in 12 levels of thrilling action. However, the park has more dinosaurs and some new species as well. When the action becomes too intense, you can team up with a friend thanks to the two-player option. Try to seal away the dinosaurs from hurting anyone else in the future with Jurassic Park Part 2: The Chaos Continues.' FROM games WHERE igdb_id = 10677 ON CONFLICT (game_id, language_code) DO NOTHING;
