INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Magical Shop', 'Magical Shop is an add-on peripheral, which plugs permanently into the Casio Loopy, allowing players to take screen captures at any time and then print them. The device also came with its own in-built editing software, which becomes active when no cartridge is present in the slot. The software is capable of making modifications to prefabricated photos or saved screen captures. The art tools include image cropping, adding text, colors. Objects, and speech bubbles.' FROM games WHERE igdb_id = 293881 ON CONFLICT (game_id, language_code) DO NOTHING;
