INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Touché: The Adventures of the Fifth Musketeer', 'Touché: The Adventures of the Fifth Musketeer is a humorous, inventory-based point and click adventure game. By right-clicking on a hotspot a context-sensitive action interface pops up, showing the relevant actions. The game is a full talkie with captions, music and sound effects. It features a progressive traveling map, which allows to visit new locations after having solved various puzzles.' FROM games WHERE igdb_id = 13788 ON CONFLICT (game_id, language_code) DO NOTHING;
