INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Advanced Civilization', 'Advanced Civilization is a game of skill for two to seven players. It covers the development of ancient civilizations from the invention of agriculture circa 8000 B.C. to the emergence of Rome around the middle of the third century B.C. Each player leads a nation of peoples over a mapboard of the Eastern Mediterranean and Near East as they attempt to carve a niche for themselves and their culture.' FROM games WHERE igdb_id = 14433 ON CONFLICT (game_id, language_code) DO NOTHING;
