INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lucky Stars Video Slots', 'Lucky Stars Video Slots is a single-player, shareware slot machine game. This game is based on an old fashioned three reel slot machine and pays out on three horizontal, three vertical and two diagonal lines. The stake / bet can be varied by the player and additional credits can be borrowed when required. The game has sound, and a save/load function The full version has an additional Hi/Lo card game in which the player can gamble their winnings.' FROM games WHERE igdb_id = 175990 ON CONFLICT (game_id, language_code) DO NOTHING;
