INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Caribbean Disaster', 'Are you looking for carefree holiday pleasures in a tropical island paradise? Do you like to sip ice-cold Pina Coladas from cocktail glasses with small colorful umbrellas? Do you dream of dozing under the palm trees on the sandy beach? If your answer is yes to any of these, Caribbean Disaster is the game for you. Caribbean Disaster is a savvy strategy game that breaks the mold of the genre, gets your brain working at peak performance, and pushes your sense of humor to the limit. The game features scrollable island views with variable zoom, animated locations, and complex strategy game-play.' FROM games WHERE igdb_id = 74056 ON CONFLICT (game_id, language_code) DO NOTHING;
