INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'College Football''s National Championship II', 'It still has the standard set of modes such as Exhibition, Tournament and Season and updated rosters for the top schools of the time, reflecting the 1994 season. There are 32 teams with five added ones to this version (Wisconsin, North Carolina, Colorado State, Oregon and Washington State), however to add these schools five others were taken out that were in the previous game (San Diego State, Pitt, LSU, Arkansas and Houston). It also keeps track of 19 different stats along with authentic offensive and defensive plays attributed to each team.' FROM games WHERE igdb_id = 46535 ON CONFLICT (game_id, language_code) DO NOTHING;
