INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hodj ''n'' Podj', 'Hodj ''n'' Podj is a computer board game and minigame compilation for one to two players. It is set in a fairy tale world, in the kingdom of Po-Poree, whose twin princesses Mish and Mosh have been kidnapped by the villainous Salmagundi. The player controls the suitor Hodj, and races the competing suitor Podj—controlled by the computer or a second player—to rescue the princesses first. Each turn, a spinner randomly determines the distances Hodj and Podj may travel across the game board, which has 19 important locations and a different minigame the player completes to earn items or information necessary to rescue the princesses.' FROM games WHERE igdb_id = 79050 ON CONFLICT (game_id, language_code) DO NOTHING;
