INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spot Goes to Hollywood', 'The central character in the game is, of course, Spot. Spot has somehow become trapped in a movie projector. As he jumps from film to film, he encounters many classic film genres; these make up the various levels of the game. The main levels are a pirate movie, an adventure movie, and a horror movie, but there are many other bonus films to unlock.' FROM games WHERE igdb_id = 4454 ON CONFLICT (game_id, language_code) DO NOTHING;
