INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Masters: Harukanaru Augusta 3', 'Masters: Harukanaru Augusta 3 is a golf sim and the third game in T&E Soft''s Harukanaru Augusta franchise. Like its predecessors, it is officially endorsed by the Masters Tournament golf competition and by Augusta National Golf Club, where the Masters takes place. The game uses digitized photos for its golfers and crowds, as well as for menus and the title screen, for a sense of realism. The game also produces weather effects that can modify the course.' FROM games WHERE igdb_id = 268542 ON CONFLICT (game_id, language_code) DO NOTHING;
