INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sterling Sharpe: End 2 End', 'End 2 End is a football game with the main attraction of it being that it has the personal endorsement of former Green Bay Packer, Sterling Sharpe. Game modes consist of Exhibition, Playoff and All-Star, however there is no Season mode. The game features 30 different teams modeled after their NFL counterparts except that their nicknames and logos are absent from the game as well as their being no actual NFL players.' FROM games WHERE igdb_id = 38434 ON CONFLICT (game_id, language_code) DO NOTHING;
