INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Multimedia Shinsho: Driving School - Futsu Menkyoka-hen', 'This program is made to teach the player how to drive and to test them on the dos and don''ts of driving. This comes in the form of true or false questions in a limited time either during a simulated drive or during a driving school examination. Correct answers grant the player points on their driving license, while incorrect answers lose points and/or health in the case of the simulated drive.' FROM games WHERE igdb_id = 245253 ON CONFLICT (game_id, language_code) DO NOTHING;
