INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'PC Fútbol 4.0', 'The fourth edition of PC Fútbol is dated for the 1995/1996 league. The game is an managerial simulator where you have to decide the training of the players, the transfers inter clubs, the number of locations of the stadium and a lot of more things.
