INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Big Sky Trooper', 'On day an alien race of slugs is out patrolling space, when they encounter the Lucasarts logo. The logo, as we all know looks like a statue of a person with his hands extending towards the sky. Seeing this logo, the slugs determine that ours is a race made up of BONES and of ADVERTISING, two things the slugs simply hate. So they attack.' FROM games WHERE igdb_id = 42640 ON CONFLICT (game_id, language_code) DO NOTHING;
