INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Disney''s Animated Storybook: Pocahontas', 'In this game you revisit the story of Disney’s Pocahontas in an interactive storybook format. Each page contains a scene from the movie with narrated text, and multiple characters and objects can be interacted with to trigger short animations accompanied by the movie’s score. Additonal features are the option to highlight words to be explained as as well as four mini games: shooting with a bow, catching berries, playing hide-and-seek with Meeko and finding the right homes for the forest’s animals.' FROM games WHERE igdb_id = 134224 ON CONFLICT (game_id, language_code) DO NOTHING;
