INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gravity Power', 'Gravity Power was a specially licensed version of Gravity Force II for the staff of Amiga Power magazine. As such it was only released on that magazine''s issue 50 cover disk.  It features single player missions and a 2-player multiplayer mode. The aim is to pilot a spacecraft through subterranean caverns avoiding enemy fire. The ship is subject to gravity and inertia and colliding with terrain or the walls of the cave results in destruction of the ship.' FROM games WHERE igdb_id = 28390 ON CONFLICT (game_id, language_code) DO NOTHING;
