INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Telebradesco Residência', 'Telebradesco Residência was a home banking cartridge that provided access to Banco Bradesco bank account information directly from your Mega Drive. The cartridge cost around 13-14 reais for pre-existing accounts or given for free to new ones and had a 3,95 monthly fee to access the service.' FROM games WHERE igdb_id = 298360 ON CONFLICT (game_id, language_code) DO NOTHING;
