INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('triple-play-96', 46245, '1995-04-18', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5p3p.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Triple Play 96', 'Triple Play 96 is one of the earliest entries in EA''s Triple Play series that featured a full MLB and MLBPA license with many of the top players of the 1995 season along with authentic stadiums from all 28 MLB teams along with 2,500 frames of animation to give the game a more realistic feel. Many of the standard options are present such as exhibition, season, playoffs, etc. along with a battery back-up that can keep extensive track on 25 different stat categories and has 12 unique pitches that can be chosen during the game. Players can also create their own baseball player and use them in the game or go against four friends.' FROM games WHERE igdb_id = 46245 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 46245 AND ge.slug = 'sport' ON CONFLICT DO NOTHING;
