INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'ScruTiny in the Great Round', 'Enter a magically interactive dreamscape through which you wander and make astonishing discoveries. Or just relax and savor the paintings, poetry and music that ebb and flow at your command. Navigate through a banquet of interwoven images, metaphoric icons, audible symbols, and words.' FROM games WHERE igdb_id = 172409 ON CONFLICT (game_id, language_code) DO NOTHING;
