INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bronkie the Bronchiasaurus', 'You must help Bronkie and Rexo find the lost machine pieces by blowing away dust with your lungs, and hitting enemies with your dusters, before the dust returns and everyone chokes on the dust! But don''t run into cigarrette smoke or dust storms, otherwise your vision will get darker, and you''ll have a hard time finding out where to go, running into enemies all around!' FROM games WHERE igdb_id = 42624 ON CONFLICT (game_id, language_code) DO NOTHING;
