INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Teenage Mutant Ninja Turtles: Dimension X Assault', 'Teenage Mutant Ninja Turtles: Dimension X Assault is a stand-alone handheld video game developed by Tiger Electronics, and released in 1995. It is the only video game to utilize any content from the Red Sky episodes of the 1987 Teenage Mutant Ninja Turtles series. The character artwork on the packaging and label is by Ken Mitchroney and Chris Allan, artists on Teenage Mutant Ninja Turtles Adventures.' FROM games WHERE igdb_id = 198938 ON CONFLICT (game_id, language_code) DO NOTHING;
