INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chou Kyuukai Miracle Nine', 'Chou Kyuukai Miracle Nine is an isometric-projection baseball game. When batting, the D-pad moves around and A and C swing. When pitching, Left and Right move around and C pitches. You can also take control of the rest of the team when the ball has been hit: you control the player with the ball; the D-pad moves around and C throws the ball.' FROM games WHERE igdb_id = 45733 ON CONFLICT (game_id, language_code) DO NOTHING;
