INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Book of Lulu', 'The Book of Lulu is an interactive multimedia book by Romain Victor-Pujebet where player can flip the pages to read through and click on various images in the book. Certain images in the book allow for slide changes or result in a small video animation, while others open in full screen mode with ability to interact with them by clicking on a certain area. Interactive images allow changes such as changing the sky, weather, season, colors and mode, while interactive videos let you interact with objects and characters which result in a short FMV sequence.' FROM games WHERE igdb_id = 281295 ON CONFLICT (game_id, language_code) DO NOTHING;
