INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mario''s Super Picross', 'Mario''s Super Picross is the first sequel to the Game Boy game, Mario''s Picross, and can be played on the Super Famicom. After the commercial failure of Mario''s Picross in the West, this sequel was released only in Japan. The game plays much the same way as the first, except Wario appears in it and presents his own set of special rules, which also return in the sequel. Other features includes game-saves, hints and tutorials.' FROM games WHERE igdb_id = 80174 ON CONFLICT (game_id, language_code) DO NOTHING;
