INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rave Racer', 'Rave Racer is an arcade racing game that can be played by two people per cabinet for up to eight players total when up to four of them were linked together. It is the third arcade title in the Ridge Racer series and the follow-up to Ridge Racer and Ridge Racer 2 - and it added three new tracks to the original one, twelve new songs to the original five, force feedback steering and improved car and racetrack graphics.' FROM games WHERE igdb_id = 39713 ON CONFLICT (game_id, language_code) DO NOTHING;
