INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pang! 3', 'Your character is locked inside an art museum and has to avoid bouncing balloons of various sizes, most of which split when hit. The player has the option of "normal" play with stages or "panic" mode in which balloons will appear continuously. In normal mode, watch out for characters like birds and dogs that will paralyze your character.' FROM games WHERE igdb_id = 39510 ON CONFLICT (game_id, language_code) DO NOTHING;
