INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blood Bath at Red Falls', 'Blood Bath At Red Falls is a high-dosage shoot-em-up that pumps fast, fluid, full-screen video into the heart of your computer. Blood Bath''s interface is classic and pure shooting gallery. Underworld uses a new video compression scheme that brings smooth animation to even the slowest computers. Blood Bath is never interrupted by stop-gap frames and video sequence loading typical of games utilizing digitized video. In Blood Bath, the action is fast and furious like a shoot-out should be.' FROM games WHERE igdb_id = 113989 ON CONFLICT (game_id, language_code) DO NOTHING;
