INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Naxat Cup Satellaview Bass Tournament "Big Fight"', 'Naxat Cup Satellaview Bass Tournament "Big Fight" is a Downloadable 4-part Soundlink game for the Satellaview that was broadcast between December 1, 1995 and June 1, 1996. It is a pseudo-sequel to Super Fishing - Big Fight. The player competes in the sum of weight of Black Basses within the limited time. To apply the contest, player sends passwords shown in the result scene. Some prizes went to the best performer.' FROM games WHERE igdb_id = 150171 ON CONFLICT (game_id, language_code) DO NOTHING;
