INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'BS Parlor! Parlor!', 'BS Parlor! Parlor! is a Downloadable 2-part Soundlink game for the Satellaview that was broadcast between March 1, 1998 and March 14, 1998. At various times throughout 1995, the game was accompanied by full-day broadcasts of a strategy magazine entitled BS Parlor! Parlor! Kouryaku Magazine.' FROM games WHERE igdb_id = 134433 ON CONFLICT (game_id, language_code) DO NOTHING;
