INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Teletransport Smurf', 'The game consists mostly of mini-games, such as spotting Brainy in a crowd photo or blowing out the candles on Lazy''s birthday cake. The player is to win these games in order to gain dewdrops, which serve as currency and points. The specific components the player needs to gather (and the amount of said components) are randomly generated at the start of the game.' FROM games WHERE igdb_id = 135833 ON CONFLICT (game_id, language_code) DO NOTHING;
