INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Abel: Shin Mokushiroku Taisen', 'Abel is a turn-based Japanese-style RPG set in a dark futuristic environment. The player commands Abel and his teammates from the headquarters, where they can rest, receive items, and prepare for the next mission. The missions themselves take place in large dungeon-like areas. Randomly appearing enemies must be defeated in first-person perspective combat with a rather standard system: characters either attack physically, use items, or execute special attacks that require "special points" (equivalent to magic). There is also an Auto option for battles.' FROM games WHERE igdb_id = 299785 ON CONFLICT (game_id, language_code) DO NOTHING;
