INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Speedy Gonzales: Los Gatos Bandidos', 'The gameplay in Speedy Gonzales resembles the Sonic the Hedgehog series of games more than anything else. For the most part Speedy will run, run across fields and up slopes and into tunnels. There are also mousetraps which function similarly to Sonic''s trampolines and will propel Speedy into the air. Speedy has a short range kick for attacking and can occasionally pick up items and use them at a later time.' FROM games WHERE igdb_id = 8076 ON CONFLICT (game_id, language_code) DO NOTHING;
